      "content": "{\n  \"name\": \"dsh-verify\",\n  \"version\": \"0.9.6\",\n  \"description\": \"Witness — browser acceptance checks for agent-built web apps. CLI, MCP, AI-drafted checklists, visual regression, and multi-browser reports.\",\n  \"keywords\": [\n    \"deepseek\",\n    \"agent\",\n    \"ai-agent\",\n    \"llm\",\n    \"mcp\",\n    \"mcp-server\",\n    \"acceptance-testing\",\n    \"e2e\",\n    \"browser-automation\",\n    \"playwright\",\n    \"visual-regression\",\n    \"verification\",\n    \"dsh\",\n    \"cordis\"\n  ],\n  \"type\": \"module\",\n  \"bin\": {\n    \"dsh-verify\": \"bin/verify.mjs\",\n    \"dsh-verify-mcp\": \"mcp/server.mjs\"\n  },\n  \"files\": [\n    \"bin/\",\n    \"cordis.patch.yml\",\n    \"mcp/\",\n    \"dsh/\",\n    \"templates/\",\n    \"demo/\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"CHANGELOG.md\",\n    \"scripts/\"\n  ],\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/263311487-ux/dsh-verify.git\"\n  },\n  \"scripts\": {\n    \"test\": \"node --test\",\n    \"demo:buggy\": \"node bin/verify.mjs --spec demo/buggy.json --out /tmp/dshv-buggy\",\n    \"demo:fixed\": \"node bin/verify.mjs --spec demo/fixed.json --out /tmp/dshv-fixed\",\n    \"ci\": \"npm test && node bin/verify.mjs --spec demo/fixed.json --out /tmp/dshv-ci-fixed && node scripts/check-buggy.mjs\",\n    \"prepublishOnly\": \"npm run ci && node scripts/smoke-pack.mjs\",\n    \"smoke\": \"npm run ci && node scripts/smoke-pack.mjs\"\n  },\n  \"dependencies\": {\n    \"@modelcontextprotocol/sdk\": \"^1.32.1\",\n    \"playwright\": \"^1.62.1\",\n    \"pngjs\": \"^7.0.0\"\n  },\n  \"overrides\": {\n    \"fast-uri\": \"^3.1.8\",\n    \"hono\": \"^4.13.7\",\n    \"ip-address\": \"^10.7.1\",\n    \"proxy-addr\": \"^2.0.8\",\n    \"qs\": \"^6.16.0\"\n  },\n  \"license\": \"MIT\",\n  \"author\": \"Bai Xing (白星) <263311487@qq.com>\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch