      "path": "dsh/plugin.mjs",
      "content": "// dsh/plugin.mjs — DeepSeek Harness (Cordis) plugin entry for dsh-verify.\n// cordis.patch.yml references name: dsh-verify; Cordis resolves this module\n// through package.json main and loads the name + apply exports.\nimport { spawnSync } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\n\nexport const name = 'dsh-verify';\nexport const inject = ['tools'];\n\nexport function apply(ctx) {\n  import('@deepseek-ai/dsh-tools')\n    .then(({ defineTool }) => {\n      ctx.tools.register(defineTool({\n        name: 'dsh_verify',\n        description: 'Witness — independent browser acceptance testing for agent-built web apps. Runs the dsh-verify CLI (real browser; PASS/FAIL with evidence receipts). Use when the agent built or changed a web app and must prove it works in a real browser.',\n        parameters: {\n          spec: { type: 'string', required: true, description: 'Path or glob to a JSON acceptance spec, e.g. specs/landing.json' },\n          url: { type: 'string', description: 'Target URL; overrides spec.serve / spec.base / step path' },\n          out: { type: 'string', description: 'Output directory for report.html + screenshots (default: ./dsh-verify-out)' },\n          browser: { type: 'string', enum: ['chromium', 'firefox', 'webkit'], description: 'Browser engine (default: chromium)' },\n        },\n        output: {\n          schema: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              ok: { type: 'boolean', required: true },\n              exitCode: { oneOf: [{ type: 'integer' }, { type: 'null' }], required: true },\n              summary: { type: 'string' },\n              report: { type: 'string' },\n              stderr: { type: 'string' },\n            },\n          },\n          render(_args, value) {\n            const v = value ?? {};\n            const lines = [];\n            lines.push('dsh-verify: ' + (v.ok ? 'PASS' : 'FAIL') + ' (exit ' + (v.exitCode ?? 'n/a') + ')');\n            if (v.summary) lines.push(v.summary);\n            return [{ type: 'text', text: lines.join('\\n') }];\n          },\n        },\n        async execute(args) {\n          const bin = fileURLToPath(new URL('../bin/verify.mjs', import.meta.url));\n          const argv = [bin, '--json', '--spec', String(args.spec)];\n          if (args.url) argv.push('--url', String(args.url));\n          if (args.out) argv.push('--out', String(args.out));\n          if (args.browser) argv.push('--browser', String(args.browser));\n          const r = spawnSync(process.execPath, argv, { encoding: 'utf8', timeout: 180000, maxBuffer: 16 * 1024 * 1024 });\n          const stdout = (r.stdout || '').trim();\n          const stderr = (r.stderr || '').trim();\n          return {\n            ok: r.status === 0,\n            exitCode: r.status,\n            summary: stdout.split('\\n').slice(-6).join('\\n'),\n            report: stdout.slice(0, 8000),\n            stderr: stderr.slice(0, 2000),\n          };\n        },\n      }));\n    })\n    .catch(() => {});\n}\n"
    },
    {
      "path": "mcp/server.mjs",
      "content": "#!/usr/bin/env node\n// dsh-verify MCP server — let any AI agent (Claude Code, Cursor, Copilot, ...)\n// run real-browser acceptance checks on its own deliverables.\n// Agents self-test and pass. Real browsers tell the truth.\nimport { Server } from '@modelcontextprotocol/sdk/server/index.js';\nimport { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';\nimport {\n  CallToolRequestSchema,\n  ListToolsRequestSchema,\n} from '@modelcontextprotocol/sdk/types.js';\nimport { runOne } from '../bin/verify.mjs';\nimport { extractPageFacts, generateSpec } from '../bin/gen.mjs';\nimport { writeFile, mkdtemp, access } from 'node:fs/promises';\nimport { tmpdir } from 'node:os';\nimport { join, resolve } from 'node:path';\nimport { chromium } from 'playwright';\nimport { createRequire } from 'node:module';\n\nconst require = createRequire(import.meta.url);\nconst VERSION = require('../package.json').version;\n\nconst server = new Server(\n  { name: 'dsh-verify', version: VERSION },\n  { capabilities: { tools: {} } },\n);\n\nserver.setRequestHandler(ListToolsRequestSchema, async () => ({\n  tools: [\n    {\n      name: 'verify_spec',\n      description:\n        'Run a dsh-verify acceptance spec (JSON file, or glob) against a real headless Chromium. ' +\n        'The spec may serve a local static dir (spec.serve) or target any URL (spec.base / step.url). ' +\n        'Returns PASS/FAIL with per-step results and a self-contained HTML report path. ' +\n        'Exit-code semantics: ok=true means every step passed. This is deterministic — no LLM judges the outcome.',\n      inputSchema: {\n        type: 'object',\n        properties: {\n          specPath: { type: 'string', description: 'Path to the spec JSON file or glob (e.g. specs/*.json)' },\n          out: { type: 'string', description: 'Output dir for report.html + screenshots (default: ./dsh-verify-out)' },\n          url: { type: 'string', description: 'Optional target URL override (spec.base / step path ignored)' },\n          headed: { type: 'boolean', description: 'Run with a visible browser (debug only)' },\n        },\n        required: ['specPath'],\n      },\n    },\n    {\n      name: 'verify_url',\n      description:\n        'Verify a live URL against a list of human-style checks, driven by a real headless Chromium. ' +\n        'Checks are dsh-verify steps: goto/click/fill/wait/expect_text/expect_class/capture_style/' +\n        'expect_style_changed/expect_url_contains/expect_navigation/expect_console_errors/' +\n        'expect_network_errors/screenshot. If no goto step is given, a goto to the url is prepended. ' +\n        'Returns PASS/FAIL with per-step results and a self-contained HTML report path. Deterministic — no LLM judges the outcome.',\n      inputSchema: {\n        type: 'object',\n        properties: {\n          url: { type: 'string', description: 'Target URL to open' },\n          checks: {\n            type: 'array',\n            description: 'Human-style checks, e.g. [{action:\"click\",selector:\"#dark-toggle\"}, {action:\"capture_style\",selector:\"body\",prop:\"backgroundColor\",var:\"bg\"}, {action:\"expect_style_changed\",selector:\"body\",prop:\"backgroundColor\",var:\"bg\"}]',\n            items: { type: 'object' },\n          },\n          out: { type: 'string', description: 'Output dir for report.html + screenshots (default: ./dsh-verify-out)' },\n          headed: { type: 'boolean', description: 'Run with a visible browser (debug only)' },\n        },\n        required: ['url', 'checks'],\n      },\n    },\n    {\n      name: 'generate_and_verify',\n      description:\n        'AI-drafts an acceptance checklist for a URL (LLM writes it, a real browser executes it), then immediately runs it in real Chromium. ' +\n        'Pass requirements as a plain-language description of what a human QA should verify (e.g. \"dark-mode toggle changes the background color\"). ' +\n        'Requires DEEPSEEK_API_KEY or OPENAI_API_KEY in the server environment. Returns the drafted spec path plus the PASS/FAIL verdict, per-step results and report path.',\n      inputSchema: {\n        type: 'object',\n        properties: {\n          url: { type: 'string', description: 'Target URL to verify' },\n          requirements: { type: 'string', description: 'Plain-language QA requirements (optional)' },\n          out: { type: 'string', description: 'Output dir for spec + report (default: ./dsh-verify-out)' },\n          model: { type: 'string', description: 'LLM model (default: deepseek-v4-flash)' },\n          headed: { type: 'boolean', description: 'Run with a visible browser (debug only)' },\n        },\n        required: ['url'],\n      },\n    },\n    {\n      name: 'health',\n      description: 'Check that the dsh-verify MCP server and its Chromium browser are ready to run verifications.',\n      inputSchema: { type: 'object', properties: {} },\n    },\n  ],\n}));\n\nasync function chromiumInstalled() {\n  try {\n    await access(chromium.executablePath());\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nasync function verify(spec, outDir, opts) {\n  const r = await runOne(spec, outDir, opts);\n  return {\n    ok: r.ok,\n    passed: r.passed,\n    total: r.total,\n    failed: r.failed,\n    report: r.report,\n  };\n}\n\nserver.setRequestHandler(CallToolRequestSchema, async (req) => {\n  const { name, arguments: args } = req.params;\n  const out = args?.out ? resolve(String(args.out)) : resolve('dsh-verify-out');\n  try {\n    if (name === 'verify_spec') {\n      if (!args?.specPath) throw new Error('specPath is required');\n      const result = await verify(resolve(String(args.specPath)), out, {\n        headed: !!args.headed,\n        url: args.url ? String(args.url) : undefined,\n      });\n      return { content: [{ type: 'text', text: JSON.stringify(result) }] };\n    }\n    if (name === 'verify_url') {\n      const url = args?.url;\n      const checks = args?.checks;\n      if (!url) throw new Error('url is required');\n      if (!Array.isArray(checks) || checks.length === 0) throw new Error('checks must be a non-empty array');\n      const steps = checks.some((c) => c.action === 'goto')\n        ? checks\n        : [{ action: 'goto', url: String(url) }, ...checks];\n      const dir = await mkdtemp(join(tmpdir(), 'dshv-mcp-'));\n      const specPath = join(dir, 'spec.json');\n      await writeFile(specPath, JSON.stringify({ title: `verify ${url}`, base: String(url), steps }, null, 2));\n      const result = await verify(specPath, out, { headed: !!args.headed });\n      result.generatedSpec = specPath;\n      return { content: [{ type: 'text', text: JSON.stringify(result) }] };\n    }\n    if (name === 'generate_and_verify') {\n      const url = args?.url;\n      if (!url) throw new Error('url is required');\n      const browser = await chromium.launch({ headless: !(args?.headed) });\n      let facts;\n      try {\n        const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });\n        await page.goto(String(url), { waitUntil: 'load', timeout: 20000 });\n        facts = await extractPageFacts(page);\n      } finally {\n        await browser.close().catch(() => {});\n      }\n      const { spec } = await generateSpec({\n        url: String(url),\n        requirements: args?.requirements ? String(args.requirements) : '',\n        pageFacts: facts,\n        model: args?.model ? String(args.model) : undefined,\n      });\n      const specPath = join(out, 'generated-spec.json');\n      const { mkdir } = await import('node:fs/promises');\n      await mkdir(out, { recursive: true });\n      await writeFile(specPath, JSON.stringify(spec, null, 2));\n      const result = await verify(specPath, out, { headed: !!args.headed });\n      result.spec = specPath;\n      return { content: [{ type: 'text', text: JSON.stringify(result) }] };\n    }\n    if (name === 'health') {\n      return {\n        content: [{\n          type: 'text',\n          text: JSON.stringify({\n            status: 'ok',\n            server: `dsh-verify MCP ${VERSION}`,\n            chromiumInstalled: await chromiumInstalled(),\n            fix: 'if chromiumInstalled is false, run: npx playwright install chromium',\n          }),\n        }],\n      };\n    }\n    throw new Error(`unknown tool: ${name}`);\n  } catch (e) {\n    return {\n      content: [{ type: 'text', text: JSON.stringify({ ok: false, error: String((e && e.message) || e) }) }],\n      isError: true,\n    };\n  }\n});\n\nconst transport = new StdioServerTransport();\nawait server.connect(transport);\n"
    },
    {
      "path": "bin/verify.mjs",
      "content": "#!/usr/bin/env node\n// dsh-verify — independent browser acceptance testing for agent deliverables.\n// Agents self-test and pass; real browsers tell the truth.\nimport { chromium, firefox, webkit } from 'playwright';\nimport { readFile, writeFile, mkdir, readdir, stat } from 'node:fs/promises';\nimport pngjs from 'pngjs';\nconst { PNG } = pngjs;\nimport { createServer } from 'node:http';\nimport { extname, join, resolve, dirname, basename, sep } from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst ROOT = dirname(fileURLToPath(import.meta.url));\nconst HELP = `dsh-verify — independent browser acceptance testing for agent deliverables\nAgents self-test and pass. Real browsers tell the truth.\n\nusage: dsh-verify --spec <spec.json|glob> [options]\n       dsh-verify init [directory]   create a zero-key starter (new directory only)\n\noptions:\n  --spec <file>   JSON acceptance spec; supports globs like \"specs/*.json\" (required)\n  --out <dir>     output dir for report.html + screenshots (default: ./dsh-verify-out)\n  --url <url>     target URL; overrides spec.serve / spec.base / step path\n  --headed        run with a visible browser\n  --browser <b>   chromium | firefox | webkit (default: chromium; overrides spec.browser)\n  --update-baselines  refresh screenshot baselines instead of failing\n  --json          print a machine-readable verdict object to stdout\n  --help          show this help\n\nactions:\n  goto wait click fill expect_text expect_class capture_style\n  expect_style_changed expect_url_contains expect_navigation\n  expect_console_errors expect_network_errors screenshot\n  capture_baseline expect_screenshot (visual regression)\n\ndocs: https://github.com/263311487-ux/dsh-verify\n`;\n\nconst MIME = { '.html':'text/html', '.htm':'text/html', '.js':'text/javascript', '.mjs':'text/javascript', '.css':'text/css', '.json':'application/json', '.png':'image/png', '.jpg':'image/jpeg', '.jpeg':'image/jpeg', '.gif':'image/gif', '.svg':'image/svg+xml', '.ico':'image/x-icon', '.txt':'text/plain', '.md':'text/markdown', '.woff2':'font/woff2', '.pdf':'application/pdf' };\n\nfunction arg(name, dflt) {\n  const i = process.argv.indexOf('--' + name);\n  return i !== -1 && process.argv[i + 1] ? process.argv[i + 1] : dflt;\n}\nconst has = (name) => process.argv.includes('--' + name);\n\nfunction esc(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;'); }\n\nfunction globToRegExp(glob) {\n  let out = '';\n  for (let i = 0; i < glob.length; i++) {\n    const c = glob[i];\n    if (c === '*') {\n      if (glob[i + 1] === '*') { i++; if (glob[i + 1] === '/') i++; out += '(?:.*/)?'; }\n      else out += '[^/]*';\n    } else if (c === '?') out += '[^/]';\n    else if ('\\\\^$.|+()[]{}'.includes(c)) out += '\\\\' + c;\n    else out += c;\n  }\n  return new RegExp('^' + out + '$');\n}\n\nasync function expandSpecPaths(pattern) {\n  if (!/[*?[]/.test(pattern)) return [pattern];\n  const rx = globToRegExp(pattern);\n  const star = pattern.indexOf('*');\n  const root = pattern.slice(0, star).split(sep).slice(0, -1).join(sep) || '.';\n  const found = [];\n  async function walk(dir) {\n    let entries;\n    try { entries = await readdir(dir, { withFileTypes: true }); } catch { return; }\n    for (const e of entries) {\n      const p = join(dir, e.name);\n      if (e.isDirectory()) await walk(p);\n      else if (rx.test(p)) found.push(p);\n    }\n  }\n  await walk(root);\n  return found.sort();\n}\n\nasync function serveDir(dir) {\n  const root = resolve(dir);\n  const server = createServer(async (req, res) => {\n    try {\n      const urlPath = decodeURIComponent((req.url || '/').split('?')[0]);\n      let fp = join(root, urlPath);\n      if (!fp.startsWith(root)) { res.writeHead(403); return res.end(); }\n      let st = await stat(fp).catch(() => null);\n      if (st && st.isDirectory()) fp = join(fp, 'index.html');\n      const data = await readFile(fp);\n      res.writeHead(200, { 'content-type': MIME[extname(fp).toLowerCase()] || 'application/octet-stream' });\n      res.end(data);\n    } catch {\n      res.writeHead(404); res.end('not found');\n    }\n  });\n  await new Promise((r) => server.listen(0, '127.0.0.1', r));\n  return { url: `http://127.0.0.1:${server.address().port}`, close: () => server.close() };\n}\n\nexport function comparePng(bufA, bufB, { tolerance = 10 } = {}) {\n  const a = PNG.sync.read(bufA);\n  const b = PNG.sync.read(bufB);\n  if (a.width !== b.width || a.height !== b.height) {\n    return { diffRatio: 1, diffPng: null, note: `size ${a.width}x${a.height} vs ${b.width}x${b.height}` };\n  }\n  let diffPixels = 0;\n  const diff = new PNG({ width: a.width, height: a.height });\n  const t = Math.max(0, tolerance);\n  for (let i = 0; i < a.data.length; i += 4) {\n    const delta = Math.abs(a.data[i] - b.data[i]) + Math.abs(a.data[i + 1] - b.data[i + 1]) + Math.abs(a.data[i + 2] - b.data[i + 2]);\n    if (delta > t * 3) {\n      diffPixels++;\n      diff.data[i] = 255; diff.data[i + 1] = 0; diff.data[i + 2] = 0; diff.data[i + 3] = 255;\n    } else {\n      diff.data[i + 3] = 0;\n    }\n  }\n  return { diffRatio: diffPixels / (a.width * a.height), diffPng: PNG.sync.write(diff) };\n}\n\nasync function snap(page, step) {\n  if (step.selector) {\n    return page.locator(step.selector).first().screenshot({ fullPage: step.full !== false });\n  }\n  return page.screenshot({ fullPage: step.full !== false });\n}\n\nconst BROWSERS = { chromium, firefox, webkit };\n\nexport async function runOne(specPath, outDir, { headed, url, updateBaselines, browser: browserName } = {}) {\n  const spec = JSON.parse(await readFile(specPath, 'utf8'));\n  const engine = BROWSERS[browserName || spec.browser || 'chromium'];\n  if (!engine) throw new Error(`unknown browser \"${browserName || spec.browser}\" (chromium | firefox | webkit)`);\n  const served = spec.serve ? await serveDir(spec.serve) : null;\n  const base = served ? served.url : (url || spec.base || 'http://localhost');\n  const results = [];\n  let browser = null;\n\n  const fail = (step, msg) => results.push({ ...step, ok: false, detail: msg });\n  const pass = (step, detail) => results.push({ ...step, ok: true, detail: detail || 'ok' });\n\n  try {\n    browser = await engine.launch({ headless: !headed });\n    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });\n    const consoleErrors = [];\n    const networkErrors = [];\n    page.on('pageerror', (e) => { results.push({ action: 'pageerror', ok: false, detail: String(e) }); });\n    page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(m.text()); });\n    page.on('response', (r) => { if (r.status() >= 400) networkErrors.push(`${r.status()} ${r.url()}`); });\n    page.on('requestfailed', (r) => { networkErrors.push(`failed ${r.url()}`); });\n\n    for (const step of spec.steps || []) {\n      const a = step.action;\n      try {\n        if (a === 'goto') { await page.goto(step.url || base + (step.path || '/index.html'), { waitUntil: 'load' }); pass(step, page.url()); }\n        else if (a === 'wait') { await page.waitForTimeout(step.ms || 500); pass(step, `${step.ms || 500}ms`); }\n        else if (a === 'click') {\n          const n = step.count || 1;\n          for (let i = 0; i < n; i++) { await page.click(step.selector); await page.waitForTimeout(80); }\n          pass(step, `${n}x ${step.selector}`);\n        }\n        else if (a === 'fill') { await page.fill(step.selector, step.text); pass(step, step.selector); }\n        else if (a === 'expect_text') {\n          const el = await page.locator(step.selector).first();\n          const text = (await el.textContent()).trim();\n          const target = String(step.text).trim();\n          const ok = step.exact ? text === target : text.includes(target);\n          (ok ? pass : fail)(step, `got \"${text}\"`);\n        }\n        else if (a === 'expect_class') {\n          const el = await page.locator(step.selector).first();\n          const cls = await el.getAttribute('class');\n          const present = String(step.class).split(/\\s+/).every((c) => cls && cls.split(/\\s+/).includes(c));\n          const want = step.present !== false;\n          (present === want ? pass : fail)(step, `class=\"${cls}\" want ${want ? 'has' : 'lacks'} \"${step.class}\"`);\n        }\n        else if (a === 'capture_style') {\n          const val = await page.locator(step.selector).first().evaluate((el, prop) => getComputedStyle(el)[prop], step.prop);\n          page.__vars = page.__vars || {}; page.__vars[step.var] = val;\n          pass(step, `${step.var} = ${val}`);\n        }\n        else if (a === 'expect_style_changed') {\n          const before = (page.__vars || {})[step.var];\n          const now = await page.locator(step.selector).first().evaluate((el, prop) => getComputedStyle(el)[prop], step.prop);\n          (before !== now ? pass : fail)(step, `before \"${before}\" now \"${now}\"`);\n        }\n        else if (a === 'expect_url_contains') {\n          const ok = page.url().includes(step.text);\n          (ok ? pass : fail)(step, page.url());\n        }\n        else if (a === 'expect_navigation') {\n          if (!step.to) fail(step, 'expect_navigation needs \"to\"');\n          else {\n            await page.waitForURL((u) => u.toString().includes(step.to), { timeout: step.timeout || 5000 });\n            pass(step, page.url());\n          }\n        }\n        else if (a === 'expect_console_errors') {\n          const want = step.present !== false;\n          const hasErr = consoleErrors.length > 0;\n          (hasErr === want ? pass : fail)(step, hasErr ? consoleErrors.slice(0, 3).join(' | ') : 'no console errors');\n        }\n        else if (a === 'expect_network_errors') {\n          const want = step.present !== false;\n          const hasErr = networkErrors.length > 0;\n          (hasErr === want ? pass : fail)(step, hasErr ? networkErrors.slice(0, 3).join(' | ') : 'no failed requests');\n        }\n        else if (a === 'screenshot') {\n          const png = await page.screenshot({ fullPage: step.full !== false });\n          const name = (step.name || `shot-${results.length}`).replace(/[^\\w.-]/g, '_');\n          await mkdir(outDir, { recursive: true });\n          const fp = join(outDir, name + '.png');\n          await writeFile(fp, png);\n          pass(step, name + '.png');\n        }\n        else if (a === 'capture_baseline') {\n          const png = await snap(page, step);\n          const name = (step.name || `baseline-${results.length}`).replace(/[^\\w.-]/g, '_');\n          const baseDir = join(outDir, 'baselines');\n          await mkdir(baseDir, { recursive: true });\n          await writeFile(join(baseDir, name + '.png'), png);\n          pass(step, name + '.png');\n        }\n        else if (a === 'expect_screenshot') {\n          const name = (step.name || `shot-${results.length}`).replace(/[^\\w.-]/g, '_');\n          const baseDir = join(outDir, 'baselines');\n          const basePath = join(baseDir, name + '.png');\n          const png = await snap(page, step);\n          await mkdir(baseDir, { recursive: true });\n          if (updateBaselines || !(await stat(basePath).catch(() => null))) {\n            await writeFile(basePath, png);\n            pass(step, updateBaselines ? 'baseline updated' : 'baseline created');\n          } else {\n            const base = await readFile(basePath);\n            const c = comparePng(base, png, { tolerance: step.tolerance ?? 10 });\n            const threshold = step.threshold ?? 0.01;\n            if (c.diffRatio <= threshold) {\n              pass(step, `diff ${(c.diffRatio * 100).toFixed(2)}% <= ${(threshold * 100).toFixed(2)}%`);\n            } else {\n              const diffDir = join(outDir, 'diffs');\n              await mkdir(diffDir, { recursive: true });\n              const diffRel = 'diffs/' + name + '-diff.png';\n              await writeFile(join(outDir, diffRel), c.diffPng || Buffer.from(''));\n              fail(step, `diff ${(c.diffRatio * 100).toFixed(2)}% > ${(threshold * 100).toFixed(2)}% (${c.note || diffRel})`);\n              results[results.length - 1].diff = diffRel;\n            }\n          }\n        }\n        else fail(step, `unknown action \"${a}\"`);\n      } catch (e) {\n        fail(step, String(e && e.message || e).slice(0, 300));\n      }\n    }\n  } finally {\n    if (browser) await browser.close().catch(() => {});\n    if (served) served.close();\n  }\n\n  const passed = results.filter((r) => r.ok).length;\n  const total = results.length;\n  const ok = results.every((r) => r.ok) && total > 0;\n  await mkdir(outDir, { recursive: true });\n\n  const rows = results.map((r, i) => {\n    const badge = r.ok ? '<span class=\"b ok\">✅</span>' : '<span class=\"b no\">❌</span>';\n    const shot = r.action === 'screenshot' && r.ok\n      ? `<img class=\"shot\" src=\"${esc(r.detail)}\" alt=\"${esc(r.detail)}\">` : '';\n    const diffImg = r.diff\n      ? `<img class=\"shot\" src=\"${esc(r.diff)}\" alt=\"${esc(r.diff)}\">` : '';\n    return `<div class=\"row ${r.ok ? 'pass' : 'fail'}\">\n      ${badge}<div class=\"meta\"><code>${esc(i + 1)}. ${esc(r.action)}</code>\n      ${r.selector ? ` <code>${esc(r.selector)}</code>` : ''}\n      ${r.text ? ` <code>\"${esc(r.text)}\"</code>` : ''}\n      ${r.class ? ` <code>.${esc(r.class)}</code>` : ''}\n      ${r.prop ? ` <code>${esc(r.prop)}</code>` : ''}\n      <div class=\"detail\">${esc(r.detail || '')}</div></div>${shot}${diffImg}</div>`;\n  }).join('\\n');\n\n  const html = `<!doctype html><html lang=\"zh\"><head><meta charset=\"utf-8\"><title>dsh-verify report</title>\n<style>\nbody{font-family:-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;background:#0f1117;color:#e6e8ee;margin:0;padding:32px;line-height:1.6}\n.wrap{max-width:860px;margin:0 auto}\nh1{font-size:22px;letter-spacing:.02em}\n.banner{border-r